/* HEXA BATTLEGROUNDS upgrade — PART 4 OF 6. Only for databases that already ran setup part-01…; run in order. Safe to re-run. */ create or replace function host_import_teams(p_token text, p_teams jsonb) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; r jsonb; v_salt text; v_arena uuid; v_size int; v_n int := 0; v_team teams; v_row int := 0; v_seen int[] := '{}'; v_num int; v_pin text; v_out jsonb := '[]'::jsonb; v_generated boolean; begin v_ev := _auth_host(p_token); v_size := _cfg(v_ev, 'arena_size'); if jsonb_typeof(p_teams) <> 'array' or jsonb_array_length(p_teams) = 0 then raise exception 'BAD_ROW: the file has no squads'; end if; if jsonb_array_length(p_teams) > 120 then raise exception 'BAD_ROW: at most 120 squads per import'; end if; for r in select * from jsonb_array_elements(p_teams) loop v_row := v_row + 1; if coalesce(r ->> 'number', '') !~ '^[0-9]{1,3}$' or (r ->> 'number')::int < 1 then raise exception 'BAD_ROW: row % — squad number must be 1–999', v_row; end if; v_num := (r ->> 'number')::int; if v_num = any(v_seen) then raise exception 'BAD_ROW: row % — squad % appears twice', v_row, v_num; end if; v_seen := v_seen || v_num; if coalesce(r ->> 'pin', '') <> '' and _weak_pin(r ->> 'pin') then raise exception 'BAD_ROW: row % — PIN for squad % must be 4–8 digits and not a repeated or sequential pattern', v_row, v_num; end if; if coalesce(r ->> 'map', '') <> '' and not exists (select 1 from arenas where event_id = v_ev and number::text = r ->> 'map') then raise exception 'BAD_ROW: row % — map % does not exist', v_row, r ->> 'map'; end if; if length(coalesce(r ->> 'name', '')) > 40 then raise exception 'BAD_ROW: row % — name longer than 40 characters', v_row; end if; end loop; for r in select * from jsonb_array_elements(p_teams) loop v_arena := null; if coalesce(r ->> 'map', '') <> '' then select id into v_arena from arenas where event_id = v_ev and number::text = r ->> 'map'; end if; if v_arena is null then select arena_id into v_arena from teams where event_id = v_ev and number = (r ->> 'number')::int; end if; if v_arena is null then select a.id into v_arena from arenas a where a.event_id = v_ev and a.phase = 'lobby' and (select count(*) from teams t where t.arena_id = a.id) < v_size order by a.number limit 1; end if; if v_arena is null then raise exception 'ALL_MAPS_FULL'; end if; v_generated := coalesce(r ->> 'pin', '') = ''; v_pin := case when v_generated then _new_pin(_cfg(v_ev, 'pin_length')) else r ->> 'pin' end; v_salt := _new_token(); insert into teams(event_id, arena_id, number, name, pin_salt, pin_hash) values (v_ev, v_arena, (r ->> 'number')::int, nullif(trim(r ->> 'name'), ''), v_salt, _hash(v_salt || v_pin)) on conflict (event_id, number) do update set name = coalesce(nullif(trim(r ->> 'name'), ''), teams.name), pin_salt = excluded.pin_salt, pin_hash = excluded.pin_hash, arena_id = case when (select phase from arenas where id = teams.arena_id) = 'lobby' then excluded.arena_id else teams.arena_id end returning * into v_team; if not exists (select 1 from inventory where team_id = v_team.id) then perform _add_item(v_team.id, 'pistol', 1); perform _add_item(v_team.id, 'medkit', 1); end if; v_out := v_out || jsonb_build_object('number', v_team.number, 'name', v_team.name, 'map', (select number from arenas where id = v_team.arena_id), 'pin', case when v_generated then v_pin end); v_n := v_n + 1; end loop; insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', 'import_teams', jsonb_build_object('count', v_n)); return jsonb_build_object('imported', v_n, 'squads', v_out); end $$; create or replace function host_roster(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; begin v_ev := _auth_host(p_token); return (select coalesce(jsonb_agg(jsonb_build_object('team_id', t.id, 'map', a.number, 'number', t.number, 'name', t.name, 'bus', t.bus, 'ready', t.ready, 'players', (select count(*) from players p where p.team_id = t.id and p.active)) order by a.number, t.number), '[]'::jsonb) from teams t join arenas a on a.id = t.arena_id where t.event_id = v_ev); end $$; create or replace function host_create_trial(p_code text, p_name text, p_secret text, p_arenas int default 1) returns jsonb language plpgsql security definer set search_path = public as $$ declare r jsonb; begin r := host_create_event(p_code, 'TRIAL · ' || coalesce(nullif(trim(p_name), ''), 'Rehearsal'), p_secret, p_arenas); update events set is_trial = true, settings = settings || jsonb_build_object( 'auto_pacing', 1, 'phase_schedule', '1,3,5,7', 'zone_warning', 30, 'shuttle_seconds', 12, 'roles_seconds', 12, 'recovery_seconds', 45, 'airdrop_interval', 2, 'intel_fallback', 45, 'attack_cooldown', 45, 'protect_seconds', 45, 'mission_time_pct', 70, 'airdrop_window', 90) where id = (r ->> 'event_id')::uuid; insert into audit_log(event_id, actor, action) values ((r ->> 'event_id')::uuid, 'host', 'create_trial'); return r || jsonb_build_object('trial', true); end $$;
